ALTER TABLE gc2_accounts ADD COLUMN role text NOT NULL DEFAULT 'player';
ALTER TABLE gc2_accounts ADD COLUMN onboarding_version integer NOT NULL DEFAULT 0;
ALTER TABLE gc2_accounts ADD COLUMN preferences jsonb;
ALTER TABLE gc2_oauth ADD COLUMN return_to text NOT NULL DEFAULT '/profile';
CREATE TABLE account_players (player_id uuid PRIMARY KEY REFERENCES players(id) ON DELETE CASCADE, account_id uuid NOT NULL REFERENCES gc2_accounts(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX account_players_owner ON account_players(account_id);
CREATE TABLE account_matches (account_id uuid NOT NULL REFERENCES gc2_accounts(id) ON DELETE CASCADE, run_id uuid NOT NULL, mode text NOT NULL, points integer NOT NULL, placement integer NOT NULL, completed_at timestamptz NOT NULL, PRIMARY KEY(account_id,run_id));
CREATE TABLE account_cards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES gc2_accounts(id) ON DELETE CASCADE, fingerprint text NOT NULL, origin text NOT NULL, payload jsonb NOT NULL, saved_at timestamptz NOT NULL DEFAULT now(), UNIQUE(account_id,fingerprint));
CREATE TABLE gc2_transcript_turns (session_id uuid NOT NULL REFERENCES gc2_sessions(id) ON DELETE CASCADE, id text NOT NULL, sequence integer NOT NULL, role text NOT NULL, original text NOT NULL, text text NOT NULL, language text NOT NULL, audio_ids jsonb NOT NULL DEFAULT '[]', status text NOT NULL DEFAULT 'accepted', correction text, at timestamptz NOT NULL, PRIMARY KEY(session_id,id));
CREATE TABLE gc2_analysis_runs (id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES gc2_sessions(id) ON DELETE CASCADE, version integer NOT NULL, input_hash text NOT NULL, status text NOT NULL, model text NOT NULL, result jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE gc2_comparison_summaries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES gc2_sessions(id) ON DELETE CASCADE, account_id uuid NOT NULL REFERENCES gc2_accounts(id) ON DELETE CASCADE, analysis_id uuid NOT NULL REFERENCES gc2_analysis_runs(id) ON DELETE CASCADE, revision integer NOT NULL DEFAULT 1, approved boolean NOT NULL DEFAULT false, items jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE gc2_graph_nodes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES gc2_sessions(id) ON DELETE CASCADE, account_id uuid NOT NULL REFERENCES gc2_accounts(id) ON DELETE CASCADE, analysis_id uuid NOT NULL REFERENCES gc2_analysis_runs(id) ON DELETE CASCADE, summary_id uuid REFERENCES gc2_comparison_summaries(id) ON DELETE CASCADE, scope text NOT NULL DEFAULT 'private', provenance text NOT NULL DEFAULT 'real', kind text NOT NULL, title text NOT NULL, summary text NOT NULL, experience text NOT NULL, response text NOT NULL, source text NOT NULL, turn_ids jsonb NOT NULL);
CREATE INDEX gc2_graph_owner ON gc2_graph_nodes(account_id,scope);
CREATE TABLE gc2_graph_edges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_node uuid NOT NULL REFERENCES gc2_graph_nodes(id) ON DELETE CASCADE, to_node uuid NOT NULL REFERENCES gc2_graph_nodes(id) ON DELETE CASCADE, kind text NOT NULL, reason text NOT NULL, inferred boolean NOT NULL DEFAULT true, UNIQUE(from_node,to_node,kind));
CREATE TABLE gc2_graph_embeddings (node_id uuid NOT NULL REFERENCES gc2_graph_nodes(id) ON DELETE CASCADE, view text NOT NULL, model text NOT NULL, dimensions integer NOT NULL CHECK(dimensions>0), version integer NOT NULL DEFAULT 1, values real[] NOT NULL, PRIMARY KEY(node_id,view), CHECK(cardinality(values)=dimensions));
CREATE TABLE gc2_cluster_snapshots (scope text PRIMARY KEY, version integer NOT NULL DEFAULT 1, clusters jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());

CREATE UNIQUE INDEX gc2_one_background ON gc2_jobs(session_id) WHERE status='running' AND kind IN ('batch','graph','compare');
